package com.kai.automusic;import android.content.*;import android.os.*;public class Boot extends BroadcastReceiver{public void onReceive(Context c,Intent i){android.content.SharedPreferences p=c.getSharedPreferences("music",0);if(p.getBoolean("boot",true)&&p.getBoolean("armed",false)){Intent s=new Intent(c,PlayerService.class).setAction("ARM");try{if(Build.VERSION.SDK_INT>=26)c.startForegroundService(s);else c.startService(s);}catch(Exception e){}}}}